<div class="page-title"><div><em>PAYMENTS</em><h1>Send money</h1><p>Move money securely, wherever it needs to go.</p></div></div><div class="grid transfer-grid"><section class="panel form-panel"><div class="tabs" data-ttabs><b data-t="internal" class="active">Internal</b><span data-t="domestic">Domestic</span><span data-t="international">International</span></div><?=form_open('transfer')?><label>From account</label><select name="from_account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?> — <?=money($a['available_balance'])?></option><?php endforeach?></select><label>Saved beneficiary</label><select name="beneficiary_id" data-beneficiary><option value="">Enter a new recipient</option><?php foreach($beneficiaries as $b):?><option value="<?=$b['id']?>" data-name="<?=html_escape($b['name'])?>" data-account="<?=html_escape($b['account_number'])?>" data-bank="<?=html_escape($b['bank_name'])?>"><?=html_escape($b['name'])?></option><?php endforeach?></select><div class="form-grid"><div><label>Recipient name</label><input name="recipient_name" required></div><div><label>Recipient account</label><input name="recipient_account" required></div></div><label>Recipient bank</label><input name="recipient_bank" required><div class="form-grid"><div class="swift-field" hidden><label>SWIFT / BIC code</label><input name="swift_code" placeholder="For international transfers"></div><div><label>Amount</label><input name="amount" type="number" step="0.01" min="0.01" required placeholder="$ 0.00"></div><div><label>Send on</label><input name="scheduled_for" type="date" value="<?=date('Y-m-d')?>" min="<?=date('Y-m-d')?>"></div></div><label>Payment note</label><input name="note" maxlength="255" placeholder="What is this payment for?"><input type="hidden" name="transfer_type" id="transfer-type" value="internal"><button class="btn wide">Review and submit transfer ›</button></form></section><aside class="panel transfer-info"><i>✓</i><h3>Secure transfers</h3><p>Your transfer is protected by multi-layer authentication and continuous fraud monitoring.</p><hr><b>Daily transfer limit</b><div class="progress"><i style="width:<?=min(100,round($used_today/$daily_limit*100))?>%"></i></div><small><?=money($used_today)?> used <span><?=money($daily_limit)?> limit</span></small><hr><b>International fees</b><small>International transfers carry a <?=$intl_fee_pct?>% fee<?=($intl_fee_flat>0?' + '.money($intl_fee_flat):'')?>.</small></aside></div>
<h2 class="section-title" style="margin-top:26px">Scheduled transfers</h2><section class="panel list"><?php if(!$scheduled):?><div class="bell-empty">You have no upcoming scheduled transfers.</div><?php endif?><?php foreach($scheduled as $t):?><div class="list-row"><div><b><?=html_escape($t['recipient_name'])?></b><small><?=money($t['amount'],$t['currency'])?> to <?=html_escape($t['recipient_bank'])?> · <?=date('M j, Y',strtotime($t['scheduled_for']))?></small></div><span class="status status-pending">Scheduled</span><form method="post" action="<?=site_url('transfers/'.$t['id'].'/cancel')?>" onsubmit="return confirm('Cancel this scheduled transfer?');"><button class="icon-btn danger">🗑</button></form></div><?php endforeach?></section>